    'import.hub.title': 'Configuración e importación de datos',
    'import.hub.intro': 'Trae tus registros externos a TradeOS, un paso a la vez. Los botones de importación existentes y las plantillas guardadas siguen disponibles en cada sección. Los archivos se revisan antes de guardarse en tu cuenta de negocio; el historial de importación registra quién realizó la importación.',
    'import.hub.progressSentence': '{reviewed} de {total} pasos revisados. El progreso de la lista se guarda en este navegador para tu cuenta; los conteos abajo provienen de los datos de tu negocio.',
