    'import.hub.openSettingsHint': 'Abre la configuración del negocio abajo, revisa tus datos y guárdalos. Luego vuelve aquí y marca este paso como revisado.',
    'import.hub.noColumnMap': 'Los datos históricos no requieren un mapa de columnas.',
    'import.hub.hubHint': 'Abre el Centro de datos históricos abajo para buscar registros por fecha, número de factura, cliente, proveedor o palabra clave de producto. Nada en este archivo modifica el stock ni los saldos actuales.',
    'import.hub.ol1': 'Elige el tipo de registro y sube CSV, Excel, ODS o Excel XML.',
    'import.hub.ol2': 'Carga una plantilla guardada, mapea las columnas o pide sugerencias a la IA.',
    'import.hub.ol3': 'Revisa campos faltantes, manejo de duplicados y la vista previa de datos.',
    'import.hub.ol4': 'Confirma la importación, revisa sus resultados y corrige las filas fallidas.',
    'import.hub.noMapping': 'No se requiere importación basada en mapeo aquí. Usa el Centro de datos históricos para revisar registros antiguos y buscarlos por fecha o palabra clave.',
    'import.hub.importFinished': 'Importación terminada. Revisa los registros guardados y las filas rechazadas antes de marcar este paso como revisado.',
    'import.hub.openSection': 'Abrir sección / introducir manualmente',
