    'import.hub.createdLabel': '{count} creados',
    'import.hub.failedLabel': '{count} fallidos',
    'import.hub.step1Title': 'Configuración del negocio y unidades',
    'import.hub.step1Desc': 'Revisa los datos de tu negocio, la moneda y las preferencias de facturación. Decide cómo compras y vendes: por ejemplo, una caja contiene 12 piezas.',
    'import.hub.step2Title': 'Marcas y categorías',
    'import.hub.step2Desc': 'Organiza tu catálogo. Usa nombres consistentes para que los productos importados se vinculen con la marca y categoría correctas.',
    'import.hub.step3Title': 'Clientes y proveedores',
    'import.hub.step3Desc': 'Añade a las personas a las que vendes y de las que compras antes de importar transacciones. Usa nombres y datos de contacto únicos. La asignación de clientes es opcional; importar empleados no crea cuentas de acceso.',
    'import.hub.step4Title': 'Productos y stock inicial',
    'import.hub.step4Desc': 'Añade nombres de productos, unidades, tamaños de pack y precios. El stock inicial es la cantidad en la fecha de inicio elegida. Revisa niveles de reposición, códigos de barras y ajustes de lote y caducidad antes de vender.',
    'import.hub.step5Title': 'Archivo de datos históricos',
    'import.hub.step5Desc': 'Opcional: busca ventas, compras y pagos antiguos en el Centro de datos históricos sin forzar un paso de mapeo. Este archivo es de solo lectura, no cambia stock ni saldos, y sirve para revisar por fecha, cliente, número de factura o palabra clave de producto.',
    'import.hub.step6Title': 'Equipo y revisión final',
    'import.hub.step6Desc': 'Opcional: importa tu equipo, territorios y rutas. Invita a los empleados y asigna permisos por separado. Revisa stock, saldos y una factura de muestra antes de empezar el trabajo diario.',
